 * Distinct authors of the issue's live comments (replies included). A comment
 * that was deleted no longer makes its author a participant. Order is
 * unspecified.
 */
export async function listCommentAuthorIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .selectDistinct({ authorId: comments.authorId })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
        livePredicate(comments.archivedAt, {}),
      ),
    )
    .all();
  return rows.map((row) => row.authorId as UserId);
}

export async function insertComment(
  input: CreateCommentInput,
  authorId: UserId,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

